<?php $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$query=static function(array $changes)use($filters){return http_build_query(array_filter(array_merge($filters,$changes),static fn($v)=>$v!==''&&$v!==null));};?>
