  <select name="tmdb" class="bg-slate-800 p-2 rounded"><option value="">TMDB: todos</option><option value="yes" <?=($filters['tmdb']??'')==='yes'?'selected':''?>>Con TMDB</option><option value="no" <?=($filters['tmdb']??'')==='no'?'selected':''?>>Sin TMDB</option></select>
  <select name="video" class="bg-slate-800 p-2 rounded"><option value="">Vídeo</option><?php foreach(['h264','hevc','av1','mpeg4'] as $v):?><option <?=($filters['video']??'')===$v?'selected':''?>><?=$v?></option><?php endforeach?></select>
