></div><div class="flex gap-4 text-slate-400"><span><?=$e(($m['width']&&$m['height'])?$m['width'].' × '.$m['height']:'—')?></span><span><?=$e($m['video_codec']??'—')?></span><span><?=$e($m['audio_codec']??'—')?></span><span><?=$duration?sprintf('%02d:%02d',intdiv($duration,60),$duration%60):'—'?></span></div></td></tr>
 <?php endforeach?><?php if(!$movies):?><tr><td colspan="10" class="p-12 text-center text-slate-400">No hay películas que coincidan con estos filtros.</td></tr><?php endif?></tbody></table></div>
