 <form x-show="open" x-cloak method="post" action="/movies" class="bg-slate-900 border border-slate-800 rounded-xl overflow-hidden"><?=$csrf->field()?><div class="grid grid-cols-4 bg-slate-800"><?php foreach(['Detalles','Información','Avanzado','Servidor'] as $n=>$label):?><button type="button" @click="tab=<?=$n+1?>" :class="tab===<?=$n+1?>?'bg-cyan-700':''" class="p-3"><?=$label?></button><?php endforeach?></div>
  <section x-show="tab===1" class="p-6 grid md:grid-cols-3 gap-4"><label class="md:col-span-2">Nombre<input x-model="title" required name="title" class="w-full bg-slate-800 p-2 rounded mt-1"></label><label>Año<input x-model="year" type="number" name="year" class="w-full bg-slate-800 p-2 rounded mt-1"></label><label>Idioma TMDB<select x-model="language" name="tmdb_language" class="w-full bg-slate-800 p-2 rounded mt-1"><option>es-ES</option><option>en-US</option></select></label><button type="button" @click="searchTmdb" class="self-end bg-indigo-700 p-2 rounded">Buscar en TMDB</button><span x-text="tmdbError" class="text-red-400"></span><div class="md:col-span-3 grid md:grid-cols-3 gap-3"><template x-for="m in results" :key="m.id"><button type="button" @click="selectTmdb(m)" class="text-left border border-slate-700 rounded p-3"><strong x-text="m.title"></strong><div x-text="(m.release_date||'').slice(0,4)"></div></button></template></div><input type="hidden" name="tmdb_id" :value="tmdbId"><label>Categoría<select name="category_id" class="w-full bg-slate-800 p-2 rounded mt-1"><option value="">Sin categoría</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>"><?=$e($c['name'])?></option><?php endforeach?></select></label><label class="md:col-span-2">Paquetes<select multiple name="package_ids[]" class="w-full bg-slate-800 p-2 rounded mt-1"><?php foreach($packages as $p):?><option value="<?=$p['id']?>"><?=$e($p['name'])?></option><?php endforeach?></select></label><button type="button" @click="tab=2" class="md:col-start-3 bg-cyan-700 p-2 rounded">Siguiente</button></section>
  <section x-show="tab===2" class="p-6 grid md:grid-cols-2 gap-4"><label>Título original<input name="original_title" class="w-full bg-slate-800 p-2 rounded"></label><label>Póster URL<input x-model="poster" name="poster_url" class="w-full bg-slate-800 p-2 rounded"></label><label>Backdrop URL<input x-model="backdrop" name="backdrop_url" class="w-full bg-slate-800 p-2 rounded"></label><label>Director<input name="director" class="w-full bg-slate-800 p-2 rounded"></label><label class="md:col-span-2">Descripción<textarea x-model="plot" name="description" class="w-full h-28 bg-slate-800 p-2 rounded"></textarea></label><label>Reparto<input name="cast" class="w-full bg-slate-800 p-2 rounded"></label><label>Géneros<input name="genres" class="w-full bg-slate-800 p-2 rounded"></label><button type="button" @click="tab=3" class="md:col-start-2 bg-cyan-700 p-2 rounded">Siguiente</button></section>
  <section x-show="tab===3" class="p-6 grid md:grid-cols-2 gap-4"><?php foreach(['direct_source'=>'Fuente directa','direct_stream'=>'Stream directo','native_frames'=>'Frames nativos','create_symlink'=>'Crear symlink','remove_subtitles'=>'Eliminar subtítulos','process_movie'=>'Procesar película'] as $name=>$label):?><label class="flex justify-between bg-slate-800 p-3 rounded"><?=$label?><input type="checkbox" name="<?=$name?>" value="1"></label><?php endforeach?><label>Contenedor<select name="target_container" class="w-full bg-slate-800 p-2 rounded"><option value="">Original</option><option>mp4</option><option>mkv</option><option>ts</option></select></label><button type="button" @click="tab=4" class="bg-cyan-700 p-2 rounded">Siguiente</button></section>
  <section x-show="tab===4" class="p-6 space-y-4"><select required name="library_id" class="w-full bg-slate-800 p-3 rounded"><option value="">Balanceador y biblioteca</option><?php foreach($libraries as $l):?><option value="<?=$l['id']?>"><?=$e(($l['server_name']??'Principal').' → '.$l['name'].' · '.$l['mount_path'])?></option><?php endforeach?></select><input required name="relative_path" placeholder="Movies/Película (2026).mkv" class="w-full bg-slate-800 p-3 rounded"><div class="flex justify-between"><button type="button" @click="tab=3" class="bg-slate-700 px-4 py-2 rounded">Anterior</button><button class="bg-emerald-700 px-5 py-2 rounded">Añadir y validar</button></div></section>
 </form>
</div>
<script>function movieWizard(){return{open:false,tab:1,preview:null,title:'',year:'',language:'es-ES',results:[],tmdbId:'',poster:'',backdrop:'',plot:'',tmdbError:'',searchTmdb(){this.tmdbError='';fetch('/movies/tmdb?'+new URLSearchParams({title:this.title,year:this.year,language:this.language})).then(r=>r.json()).then(r=>{if(!r.ok)throw new Error(r.error);this.results=r.data.results||[]}).catch(e=>this.tmdbError=e.message)},selectTmdb(m){this.tmdbId=m.id;this.title=m.title||this.title;this.year=(m.release_date||'').slice(0,4)||this.year;this.poster=m.poster_path?'https://image.tmdb.org/t/p/w500'+m.poster_path:'';this.backdrop=m.backdrop_path?'https://image.tmdb.org/t/p/original'+m.backdrop_path:'';this.plot=m.overview||'';this.results=[]}}}</script>
